import{_ as a,o as e,c as o,ag as r}from"./chunks/framework.C9sp7nFj.js";const u=JSON.parse('{"title":"SetCoord 设置用户坐标系","description":"","frontmatter":{},"headers":[],"relativePath":"3. 指令/5. 设置指令/SetCoord.md","filePath":"3. 指令/5. 设置指令/SetCoord.md","lastUpdated":1778862643000}'),s={name:"3. 指令/5. 设置指令/SetCoord.md"};function d(n,t,i,l,h,c){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="setcoord-设置用户坐标系" tabindex="-1">SetCoord 设置用户坐标系 <a class="header-anchor" href="#setcoord-设置用户坐标系" aria-label="Permalink to &quot;SetCoord 设置用户坐标系&quot;">​</a></h1><p>该指令用于<strong>设置并切换机器人的当前用户坐标系（User Coordinate System）</strong>。它定义了机器人运动的参考基准，允许用户在倾斜的工装、移动的平台或特定的工作表面上建立独立的坐标系，从而简化示教编程和位置偏置计算。</p><h2 id="指令格式" tabindex="-1">指令格式 <a class="header-anchor" href="#指令格式" aria-label="Permalink to &quot;指令格式&quot;">​</a></h2><p>SetCoord(Coord) SetCoord(用户坐标系参数)</p><hr><h2 id="参数详细说明" tabindex="-1">参数详细说明 <a class="header-anchor" href="#参数详细说明" aria-label="Permalink to &quot;参数详细说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>说明</th><th>默认值/备注</th></tr></thead><tbody><tr><td>Coord：用户坐标系参数（UserCoord Param）</td><td>USERCOORD 变量</td><td>指定当前需要启用的用户坐标系数据。该变量包含了用户坐标系相对于机器人基坐标系（World/Base）的偏移量和旋转角度。</td><td></td></tr></tbody></table><hr><h2 id="工作原理" tabindex="-1">工作原理 <a class="header-anchor" href="#工作原理" aria-label="Permalink to &quot;工作原理&quot;">​</a></h2><p>执行此指令后，所有以笛卡尔坐标表示的位置数据（如 <code>MovL</code> 指令中的点位）都将基于该 <strong>USERCOORD</strong> 的原点和轴向进行解析。这使得同一套程序可以通过更改坐标系偏移，轻松适配到不同的工作位置。</p><hr><h2 id="示例" tabindex="-1">示例： <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例：&quot;">​</a></h2><div class="language-estun vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">estun</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SetCoord</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(USERCOORD0)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><strong>执行结果：</strong></p><p>选择 <strong>USERCOORD0</strong>（通常为默认基坐标系）作为机器人的当前参考坐标系。</p><hr><h2 id="应用场景" tabindex="-1">应用场景 <a class="header-anchor" href="#应用场景" aria-label="Permalink to &quot;应用场景&quot;">​</a></h2><ul><li><strong>斜面作业</strong>：在倾斜的工作台上建立坐标系，使机器人的运动方向与台面平行。</li><li><strong>多工位偏移</strong>：当有多个完全相同的治具时，只需示教一个工位的程序，配合不同的 <code>SetCoord</code> 即可实现全场通用。</li><li><strong>外部输入校准</strong>：配合视觉系统，动态更新用户坐标系以补偿工件的摆放偏差。</li></ul>',18)])])}const b=a(s,[["render",d]]);export{u as __pageData,b as default};
